"""Dependency-free static assets for the Cockpit single-page interface."""

INDEX_HTML = r'''<!doctype html>
<html lang="ja">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="dark">
  <title>NEXUS SEED Cockpit</title>
  <link rel="stylesheet" href="/cockpit/styles.css">
</head>
<body>
  <div class="shell">
    <aside class="sidebar">
      <div class="brand"><span class="brand-mark">N</span><div><strong>NEXUS SEED</strong><small>HUMAN COCKPIT</small></div></div>
      <nav id="navigation" aria-label="Cockpit navigation">
        <button class="nav-item active" data-view="overview"><span>◫</span>Overview</button>
        <button class="nav-item" data-view="being"><span>◎</span>Being</button>
        <button class="nav-item" data-view="activity"><span>↳</span>Activity</button>
        <button class="nav-item" data-view="work"><span>◇</span>Work</button>
        <button class="nav-item" data-view="reviews"><span>!</span>Reviews <b id="review-nav-count"></b></button>
        <button class="nav-item" data-view="providers"><span>⌘</span>Providers</button>
        <button class="nav-item" data-view="system"><span>⋯</span>System</button>
      </nav>
      <div class="sidebar-foot">
        <div class="live-dot"><i></i><span id="sidebar-runtime">CONNECTING</span></div>
        <small id="last-update">Waiting for snapshot</small>
      </div>
    </aside>
    <section class="workspace">
      <header class="topbar">
        <div><p class="eyebrow" id="view-eyebrow">CURRENT SITUATION</p><h1 id="view-title">Overview</h1></div>
        <div class="top-actions">
          <div class="health-pill"><i></i><span id="runtime-status">Connecting</span></div>
          <button class="button primary" id="new-goal">＋ New Goal</button>
          <button class="icon-button" id="refresh" title="Refresh">↻</button>
        </div>
      </header>
      <main id="app" aria-live="polite"><div class="loading"><span></span><p>Compiling current context…</p></div></main>
    </section>
  </div>

  <dialog id="auth-dialog">
    <form method="dialog" id="auth-form" class="dialog-card">
      <p class="eyebrow">SECURE CONNECTION</p><h2>Cockpitへ接続</h2>
      <p>NEXUS_SEED_WEBHOOK_TOKENを入力してください。トークンはこのタブ内だけに保持されます。</p>
      <label>Access token<input id="auth-token" type="password" autocomplete="off" required></label>
      <div class="dialog-actions"><button class="button primary" value="default">Connect</button></div>
      <p class="form-error" id="auth-error"></p>
    </form>
  </dialog>
  <div id="toast" role="status"></div>
  <script src="/cockpit/app.js" defer></script>
</body>
</html>'''


STYLES_CSS = r'''
:root{--bg:#071019;--panel:#0c1722;--panel-2:#101e2b;--line:#20303d;--text:#e8f0f4;--muted:#8497a6;--accent:#55e6b5;--accent-2:#6da8ff;--warn:#f3bf62;--danger:#ff7f7f;--ok:#64e1a9;--radius:16px;--shadow:0 20px 60px rgba(0,0,0,.25)}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}button{color:inherit}.shell{display:grid;grid-template-columns:232px minmax(0,1fr);min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;padding:24px 16px 18px;background:#08131d;border-right:1px solid #182733;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:12px;padding:0 8px 28px}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:linear-gradient(145deg,var(--accent),#2a9779);color:#052017;font-weight:900;box-shadow:0 0 28px rgba(85,230,181,.18)}.brand strong{display:block;font-size:13px;letter-spacing:.08em}.brand small{display:block;margin-top:3px;color:var(--muted);font-size:9px;letter-spacing:.18em}nav{display:grid;gap:5px}.nav-item{display:flex;align-items:center;gap:12px;width:100%;border:0;background:transparent;padding:11px 12px;border-radius:10px;color:#93a5b2;text-align:left;cursor:pointer;transition:.18s}.nav-item span{width:18px;color:#627785;font-size:17px;text-align:center}.nav-item b{margin-left:auto;min-width:19px;padding:2px 6px;border-radius:12px;background:#513131;color:#ffaaaa;font-size:10px;text-align:center}.nav-item:hover{background:#0e1d29;color:#dfe9ef}.nav-item.active{background:#122831;color:var(--accent)}.nav-item.active span{color:var(--accent)}.sidebar-foot{margin-top:auto;padding:16px 10px 4px;border-top:1px solid var(--line)}.sidebar-foot small{display:block;margin-top:7px;color:#587080;font-size:10px}.live-dot{display:flex;align-items:center;gap:8px;color:#9db0bd;font-size:10px;font-weight:700;letter-spacing:.12em}.live-dot i,.health-pill i{width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 12px var(--accent)}.workspace{min-width:0}.topbar{min-height:94px;padding:23px 34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #172632;background:rgba(7,16,25,.86);backdrop-filter:blur(16px);position:sticky;top:0;z-index:5}.eyebrow{margin:0 0 5px;color:#668091;font-size:9px;font-weight:800;letter-spacing:.2em}.topbar h1{margin:0;font-size:23px;letter-spacing:-.02em}.top-actions{display:flex;align-items:center;gap:10px}.health-pill{display:flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid #244135;border-radius:999px;background:#0c201b;color:#a6d8c4;font-size:11px}.button,.icon-button{border:1px solid var(--line);border-radius:9px;background:#12212d;padding:9px 13px;cursor:pointer;transition:.18s}.button:hover,.icon-button:hover{border-color:#47606f;transform:translateY(-1px)}.button.primary{border-color:#33866d;background:#154b3c;color:#c9ffed;font-weight:700}.button.danger{background:#3b2025;border-color:#74353f;color:#ffc0c7}.button.small{padding:6px 9px;font-size:11px}.icon-button{width:38px;height:38px;padding:0;font-size:18px}main{padding:28px 34px 60px;max-width:1540px;margin:0 auto}.loading{height:55vh;display:grid;place-content:center;text-align:center;color:var(--muted)}.loading span{width:30px;height:30px;margin:auto;border:2px solid #263947;border-top-color:var(--accent);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.grid{display:grid;gap:16px}.metrics{grid-template-columns:repeat(6,minmax(120px,1fr));margin-bottom:18px}.metric{padding:17px 18px;border:1px solid var(--line);border-radius:var(--radius);background:linear-gradient(145deg,#0e1a25,#0b1620)}.metric .label{display:flex;align-items:center;justify-content:space-between;color:#718797;font-size:10px;text-transform:uppercase;letter-spacing:.08em}.metric strong{display:block;margin-top:13px;font-size:27px;letter-spacing:-.04em}.metric small{color:#5f7585}.metric .tone-error{color:var(--danger)}.metric .tone-warning{color:var(--warn)}.focus-card{position:relative;overflow:hidden;min-height:150px;padding:25px 27px;margin-bottom:18px;border:1px solid #275044;border-radius:20px;background:radial-gradient(circle at 90% 20%,rgba(85,230,181,.12),transparent 34%),linear-gradient(140deg,#10251f,#0b1821)}.focus-card:before{content:"";position:absolute;left:0;top:24px;bottom:24px;width:3px;background:var(--accent);box-shadow:0 0 18px var(--accent)}.focus-card h2{max-width:850px;margin:16px 0 10px;font-size:25px;font-weight:580;line-height:1.3}.focus-meta{display:flex;gap:10px;align-items:center;color:#86a295;font-size:11px}.section{margin-top:27px}.section-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:12px}.section-head h2{margin:0;font-size:15px}.section-head p{margin:0;color:var(--muted);font-size:11px}.two-col{grid-template-columns:minmax(0,1.15fr) minmax(320px,.85fr)}.three-col{grid-template-columns:repeat(3,minmax(0,1fr))}.panel{border:1px solid var(--line);border-radius:var(--radius);background:var(--panel);box-shadow:var(--shadow)}.panel-pad{padding:18px}.attention-list,.stack{display:grid;gap:9px}.attention-item{display:grid;grid-template-columns:9px minmax(0,1fr) auto;gap:13px;align-items:start;padding:14px;border:1px solid #263543;border-radius:12px;background:#0d1924}.attention-item>.signal{width:8px;height:8px;margin-top:6px;border-radius:50%;background:var(--warn);box-shadow:0 0 10px rgba(243,191,98,.25)}.attention-item.error>.signal{background:var(--danger)}.attention-item h3,.card h3{margin:0 0 4px;font-size:13px}.attention-item p,.card p{margin:0;color:var(--muted);font-size:11px;line-height:1.5}.actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.empty{padding:28px;text-align:center;color:var(--muted);border:1px dashed #2a3a46;border-radius:12px}.empty strong{display:block;margin-bottom:5px;color:#b5c3cc}.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:11px}.card{padding:16px;border:1px solid var(--line);border-radius:13px;background:var(--panel)}.card-top{display:flex;justify-content:space-between;gap:10px;align-items:start}.card .meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px;color:#6f8493;font-size:10px}.badge{display:inline-flex;align-items:center;padding:3px 7px;border:1px solid #315064;border-radius:999px;background:#102432;color:#98c3dd;font-size:9px;font-weight:800;letter-spacing:.05em}.badge.ok,.badge.ACTIVE,.badge.COMPLETED,.badge.SATISFIED,.badge.HEALTHY,.badge.CONFIRMED{border-color:#285c4d;background:#102c25;color:#78d9b6}.badge.warn,.badge.WAITING,.badge.PAUSED,.badge.REVIEW,.badge.INFERRED{border-color:#655332;background:#302617;color:#e7bd70}.badge.error,.badge.FAILED,.badge.BLOCKED,.badge.BLOCKED_CAPABILITY,.badge.BLOCKED_PROVIDER,.badge.BLOCKED_PLAN,.badge.UNAVAILABLE{border-color:#6d3940;background:#321c22;color:#f1959f}.badge.OBSERVED{border-color:#3e5574;background:#16243a;color:#8db7ee}.timeline{position:relative;display:grid;gap:12px}.activity-card{position:relative;padding:18px 18px 15px 26px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}.activity-card:before{content:"";position:absolute;left:10px;top:23px;width:6px;height:6px;border-radius:50%;background:var(--accent-2);box-shadow:0 0 12px var(--accent-2)}.activity-card .result{float:right}.activity-steps{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:13px 0;color:#9badb8;font-size:10px}.activity-steps span:not(:last-child):after{content:"→";margin-left:6px;color:#3c5362}details{margin-top:12px;border-top:1px solid #1d2d39;padding-top:10px}summary{cursor:pointer;color:#7992a2;font-size:10px}.raw{overflow:auto;max-height:340px;margin:10px 0 0;padding:12px;border-radius:9px;background:#071019;color:#9db1bf;font:10px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap}.being-hero{grid-template-columns:1fr 1fr;margin-bottom:17px}.identity{font-size:20px;margin:10px 0}.list{margin:10px 0 0;padding-left:18px;color:#a7b6c0;font-size:11px;line-height:1.7}.claim{padding:10px 0;border-bottom:1px solid #1b2a35}.claim:last-child{border:0}.claim-value{margin-top:5px;color:#aebbc4;font-size:11px}.capabilities{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}.tabs{display:flex;gap:6px;margin-bottom:13px}.tab{padding:7px 11px;border:1px solid var(--line);border-radius:9px;background:transparent;color:var(--muted);cursor:pointer}.tab.active{background:#16302a;color:var(--accent);border-color:#2d6554}.provider-health{width:10px;height:10px;border-radius:50%;background:var(--ok);box-shadow:0 0 10px rgba(100,225,169,.3)}.provider-health.bad{background:var(--danger)}dialog{border:0;padding:0;background:transparent;color:var(--text)}dialog::backdrop{background:rgba(2,7,11,.82);backdrop-filter:blur(5px)}.dialog-card{width:min(430px,calc(100vw - 32px));padding:25px;border:1px solid #2d4453;border-radius:17px;background:#0d1a25;box-shadow:var(--shadow)}.dialog-card h2{margin:5px 0 10px}.dialog-card p{color:var(--muted);font-size:12px;line-height:1.5}.dialog-card label{display:grid;gap:7px;margin-top:18px;color:#91a5b3;font-size:11px}.dialog-card input{width:100%;padding:11px;border:1px solid #304653;border-radius:9px;background:#07121b;color:var(--text)}.dialog-actions{display:flex;justify-content:flex-end;margin-top:18px}.form-error{color:var(--danger)!important}#toast{position:fixed;right:24px;bottom:24px;z-index:30;max-width:420px;padding:13px 16px;border:1px solid #32614f;border-radius:11px;background:#102b23;box-shadow:var(--shadow);color:#c8f4e3;font-size:12px;opacity:0;transform:translateY(12px);pointer-events:none;transition:.22s}#toast.show{opacity:1;transform:none}#toast.error{border-color:#733c43;background:#321d22;color:#ffc3c8}@media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}.two-col,.being-hero{grid-template-columns:1fr}.three-col{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.shell{grid-template-columns:1fr}.sidebar{position:static;width:100%;height:auto;padding:14px}.brand{padding-bottom:12px}.sidebar nav{display:flex;overflow:auto}.nav-item{width:auto;white-space:nowrap}.sidebar-foot{display:none}.topbar{padding:18px;position:static}.health-pill{display:none}.top-actions .primary{display:none}main{padding:18px}.metrics{grid-template-columns:repeat(2,1fr)}.three-col{grid-template-columns:1fr}.focus-card h2{font-size:20px}.activity-steps{display:grid}.activity-steps span:not(:last-child):after{content:"↓"}.attention-item{grid-template-columns:9px 1fr}.attention-item .actions{grid-column:2;justify-content:flex-start}}
'''


APP_JS = r'''
const state={snapshot:null,view:"overview",token:sessionStorage.getItem("nexus-cockpit-token")||"",timer:null};
const $=s=>document.querySelector(s);const app=$("#app");
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const raw=v=>`<details><summary>Raw facts / audit detail</summary><pre class="raw">${esc(JSON.stringify(v,null,2))}</pre></details>`;
const when=v=>v?new Intl.DateTimeFormat("ja-JP",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(v)):"—";
const badge=v=>`<span class="badge ${esc(v)}">${esc(v||"UNKNOWN")}</span>`;
const empty=(title,text="")=>`<div class="empty"><strong>${esc(title)}</strong>${esc(text)}</div>`;
const section=(title,sub,body)=>`<section class="section"><div class="section-head"><div><h2>${esc(title)}</h2><p>${esc(sub||"")}</p></div></div>${body}</section>`;
function headers(){return state.token?{"Authorization":`Bearer ${state.token}`}:{}}
async function load(){try{const res=await fetch("/cockpit/api/snapshot",{headers:headers(),cache:"no-store"});if(res.status===401){showAuth();return}if(!res.ok)throw new Error(`Cockpit API ${res.status}`);state.snapshot=await res.json();updateChrome();render();clearTimeout(state.timer);state.timer=setTimeout(load,5000)}catch(err){app.innerHTML=empty("Cockpit snapshotを取得できません",err.message);$("#runtime-status").textContent="Offline";$("#sidebar-runtime").textContent="OFFLINE"}}
function showAuth(){const d=$("#auth-dialog");if(!d.open)d.showModal();$("#auth-error").textContent=""}
$("#auth-form").addEventListener("submit",e=>{e.preventDefault();state.token=$("#auth-token").value.trim();sessionStorage.setItem("nexus-cockpit-token",state.token);$("#auth-dialog").close();load()});
function updateChrome(){const s=state.snapshot;$("#runtime-status").textContent=s.overview.runtime.status;$("#sidebar-runtime").textContent=`RUNTIME ${s.overview.runtime.status}`;$("#last-update").textContent=`Updated ${when(s.generated_at)}`;$("#review-nav-count").textContent=s.reviews.length||"";$("#new-goal").style.display=s.control.enabled?"":"none"}
const titles={overview:["CURRENT SITUATION","Overview"],being:["PERSISTENT BEING","Being"],activity:["CAUSAL HISTORY","Activity"],work:["DURABLE REQUIREMENTS","Work"],reviews:["HUMAN DECISIONS","Reviews"],providers:["EXECUTION FEDERATION","Providers"],system:["RUNTIME HEALTH","System"]};
document.querySelectorAll(".nav-item").forEach(b=>b.addEventListener("click",()=>{state.view=b.dataset.view;document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x===b));const t=titles[state.view];$("#view-eyebrow").textContent=t[0];$("#view-title").textContent=t[1];render()}));$("#refresh").onclick=load;
function metric(label,value,sub="",tone=""){return `<div class="metric"><div class="label"><span>${esc(label)}</span></div><strong class="${tone}">${esc(value)}</strong><small>${esc(sub)}</small></div>`}
function render(){if(!state.snapshot)return;({overview:renderOverview,being:renderBeing,activity:renderActivity,work:renderWork,reviews:renderReviews,providers:renderProviders,system:renderSystem}[state.view]||renderOverview)()}
function attention(items){if(!items.length)return empty("判断を必要とする項目はありません","Runtimeは次のEventを待っています。");return `<div class="attention-list">${items.map(x=>`<article class="attention-item ${x.severity}"><span class="signal"></span><div><h3>${esc(x.title)}</h3><p>${esc(x.message)}</p>${raw(x.raw)}</div><div class="actions">${attentionActions(x)}</div></article>`).join("")}</div>`}
function attentionActions(x){if(!state.snapshot.control.enabled)return"";if(["review","capability_acquisition"].includes(x.kind))return `<button class="button small primary" onclick="review('${esc(x.target_id)}','approve')">Approve</button><button class="button small" onclick="review('${esc(x.target_id)}','reject')">Reject</button>`;if(x.kind==="self_question")return `<button class="button small primary" onclick="answerQuestion('${esc(x.target_id)}')">Answer</button>`;if(x.kind==="blocked_work")return `<button class="button small" onclick="workCommand('resume','${esc(x.target_id)}')">Resume</button>`;return""}
function goalCard(g){return `<article class="card"><div class="card-top"><div><h3>${esc(g.title)}</h3><p>${esc(g.objective)}</p></div>${badge(g.status)}</div><div class="meta"><span>Priority ${esc(g.priority)}</span><span>${when(g.updated_at)}</span></div>${state.snapshot.control.enabled?`<div class="actions"><button class="button small" onclick="goalCommand('pause','${g.id}')">Pause</button><button class="button small" onclick="goalCommand('resume','${g.id}')">Resume</button><button class="button small danger" onclick="goalCommand('cancel','${g.id}')">Cancel</button></div>`:""}</article>`}
function intentionCard(i){return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(i.goal_title||"GOAL")}</p><h3>${esc(i.focus)}</h3></div>${badge(i.status)}</div><p>${esc(i.reason||"No additional reason recorded")}</p><div class="meta"><span>Priority ${esc(i.priority||"—")}</span><span>Updated ${when(i.updated_at)}</span></div><details><summary>Reconsideration conditions</summary><pre class="raw">${esc(JSON.stringify(i.reconsider_on,null,2))}</pre></details></article>`}
function activityCard(a){return `<article class="activity-card"><span class="result">${badge(a.result.replace(" ","_"))}</span><h3>${esc(a.title)}</h3><p class="eyebrow">${when(a.updated_at)}</p><div class="activity-steps">${a.steps.map(s=>`<span>${esc(s)}</span>`).join("")}</div>${raw(a.details)}</article>`}
function renderOverview(){const s=state.snapshot,o=s.overview,c=o.counts;app.innerHTML=`<div class="grid metrics">${metric("Runtime",o.runtime.status,"Durable runtime")}${metric("LLM",o.llm.status,o.llm.model||"Not configured")}${metric("Goals",c.active_goals,"Active")}${metric("Intentions",c.active_intentions,"Non-terminal")}${metric("Reviews",c.pending_reviews,"Waiting for human",c.pending_reviews?"tone-warning":"")}${metric("Errors / Warnings",`${c.errors} / ${c.warnings}`,"Needs attention",c.errors?"tone-error":c.warnings?"tone-warning":"")}</div><section class="focus-card"><p class="eyebrow">CURRENT FOCUS · ${esc(o.focus.disposition)}</p><h2>${esc(o.focus.label)}</h2><div class="focus-meta"><span>${esc(o.focus.source_event_type||"Persistent context")}</span><span>•</span><span>${when(o.focus.updated_at)}</span></div></section><div class="grid two-col"><div>${section("Needs Attention","Human decision and blocked conditions",attention(s.needs_attention))}</div><div>${section("Goals / Intentions","What NEXUS SEED is pursuing",`<div class="stack">${s.goals.filter(g=>g.status==="ACTIVE").slice(0,4).map(goalCard).join("")||empty("Active Goalなし")}${s.intentions.filter(i=>!["SATISFIED","ABANDONED"].includes(i.status)).slice(0,3).map(intentionCard).join("")}</div>`)}</div></div>${section("Recent Activity","Events grouped into human-readable causal activity",`<div class="timeline">${s.activities.slice(0,6).map(activityCard).join("")||empty("Activityはまだありません")}</div>`)}`}
function listBlock(items,none="None"){return items?.length?`<ul class="list">${items.map(x=>`<li>${esc(typeof x==="string"?x:JSON.stringify(x))}</li>`).join("")}</ul>`:empty(none)}
function renderBeing(){const b=state.snapshot.being,self=b.self,master=b.master;const claims=Object.entries(master.claims||{}).flatMap(([category,items])=>items.map(x=>({...x,category})));app.innerHTML=`<div class="grid being-hero"><article class="panel panel-pad"><p class="eyebrow">SELF PROJECTION</p><div class="identity">${esc(typeof self.identity==="string"?self.identity:JSON.stringify(self.identity)||"Identity not recorded")}</div><h3>Current concerns</h3>${listBlock(self.current_concerns,"Current concernなし")}<h3>Commitments</h3>${listBlock(self.commitments,"Commitmentなし")}<h3>Recent reflection</h3>${self.recent_reflection?raw(self.recent_reflection):empty("Reflectionはまだありません")}</article><article class="panel panel-pad"><p class="eyebrow">MASTER · ${esc(master.master_id)}</p><h3>Claims with epistemic status</h3>${claims.length?claims.map(c=>`<div class="claim"><div class="card-top"><strong>${esc(c.category)} · ${esc(c.key)}</strong>${badge(c.status)}</div><div class="claim-value">${esc(typeof c.value==="string"?c.value:JSON.stringify(c.value))}</div></div>`).join(""):empty("Master claimはまだありません","OBSERVED / INFERRED / CONFIRMEDを区別して表示します。")}</article></div><div class="grid two-col">${section("Unresolved Self Questions","Questions that may require the Master",self.unresolved_questions.length?`<div class="stack">${self.unresolved_questions.map(q=>`<article class="card"><h3>${esc(q.text)}</h3>${state.snapshot.control.enabled?`<div class="actions"><button class="button small primary" onclick="answerQuestion('${q.id}')">Answer</button></div>`:""}${raw(q.raw)}</article>`).join("")}</div>`:empty("未回答の質問はありません"))}${section("Available Capabilities","Projected live from Capability Registry",`<div class="panel panel-pad"><div class="capabilities">${self.capabilities.map(x=>`<span class="badge">${esc(x)}</span>`).join("")||"None registered"}</div></div>`)}</div>${section("Persistent Intentions","Long-lived state beneath existing Goals",`<div class="card-grid">${state.snapshot.intentions.map(intentionCard).join("")||empty("Intentionはまだありません")}</div>`)}`}
function renderActivity(){app.innerHTML=section("Activity Timeline","Process names are hidden until you open internal details",`<div class="timeline">${state.snapshot.activities.map(activityCard).join("")||empty("Activityはまだありません")}</div>`)}
function workCard(w){return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(w.type)}</p><h3>${esc(w.objective||w.type)}</h3></div>${badge(w.status)}</div><p>${esc(w.reason||"")}</p><div class="meta"><span>Priority ${esc(w.priority)}</span><span>${when(w.updated_at)}</span></div>${w.missing_capabilities?.length?`<div class="capabilities">${w.missing_capabilities.map(x=>`<span class="badge error">${esc(x)}</span>`).join("")}</div>`:""}${state.snapshot.control.enabled&&!['SATISFIED','CANCELLED'].includes(w.status)?`<div class="actions"><button class="button small" onclick="workCommand('pause','${w.id}')">Pause</button><button class="button small" onclick="workCommand('resume','${w.id}')">Resume</button><button class="button small" onclick="changePriority('${w.id}')">Priority</button><button class="button small" onclick="changeProvider('${w.id}')">Provider</button><button class="button small danger" onclick="workCommand('cancel','${w.id}')">Cancel</button></div>`:""}${raw(w)}</article>`}
function renderWork(){const w=state.snapshot.work;app.innerHTML=`${section("Active Work",`${w.active.length} durable requirements`,`<div class="card-grid">${w.active.map(workCard).join("")||empty("Active Workなし")}</div>`)}${section("Blocked Work",`${w.blocked.length} items need capability, provider, or planning recovery`,`<div class="card-grid">${w.blocked.map(workCard).join("")||empty("Blocked Workなし")}</div>`)}${section("Completed",`Most recent ${w.completed.length}`,`<div class="card-grid">${w.completed.map(workCard).join("")||empty("Completed Workなし")}</div>`)}`}
function reviewCard(r){return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(r.category)}</p><h3>${esc(r.summary)}</h3></div>${badge("REVIEW")}</div><p>${esc(r.process||r.event_type)}</p><div class="meta"><span>${when(r.created_at)}</span><span>${esc(r.id)}</span></div>${state.snapshot.control.enabled?`<div class="actions"><button class="button small primary" onclick="review('${r.id}','approve')">Approve</button><button class="button small danger" onclick="review('${r.id}','reject')">Reject</button></div>`:""}${raw(r)}</article>`}
function renderReviews(){app.innerHTML=section("Pending Reviews","All decisions go through the existing authorized Control Plane",`<div class="card-grid">${state.snapshot.reviews.map(reviewCard).join("")||empty("レビュー待ちはありません","NEXUS SEEDは人間の判断を待っていません。")}</div>`)}
function renderProviders(){app.innerHTML=section("Execution Providers","Administrative status and observed health remain distinct",`<div class="card-grid">${state.snapshot.providers.map(p=>`<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(p.kind)}</p><h3>${esc(p.name)} <small>v${esc(p.version)}</small></h3></div><span class="provider-health ${p.operational?'':'bad'}"></span></div><div class="meta">${badge(p.status)}${badge(p.health)}<span>Trust ${esc(p.trust_level)}</span></div>${raw(p)}</article>`).join("")||empty("Providerはまだ登録されていません")}</div>`)}
function renderSystem(){const s=state.snapshot;app.innerHTML=`<div class="grid metrics">${metric("Runtime",s.overview.runtime.status,"Request reached live runtime")}${metric("Phase 6",s.overview.phase6.enabled?"ON":"OFF","Feature flag")}${metric("LLM",s.overview.llm.status,s.overview.llm.model||"")}${metric("Raw trace","AVAILABLE","Audit history retained")}</div>${section("Delivery Health","Durable Event delivery",`<article class="panel panel-pad">${raw(s.system.delivery)}</article>`)}${section("Current Status Counts","Read-only projections",`<div class="grid two-col"><article class="panel panel-pad"><h3>Processes</h3>${raw(s.system.process_counts)}</article><article class="panel panel-pad"><h3>Work</h3>${raw(s.system.work_counts)}</article></div>`)}${section("Recent Failures","Human explanation appears in Needs Attention; raw facts stay here",`<div class="card-grid">${s.system.recent_failures.map(x=>`<article class="card"><h3>${esc(x.definition)}</h3>${badge(x.status)}${raw(x)}</article>`).join("")||empty("Current unresolved failureなし")}</div>`)}`}
async function sendCommand(command){try{const res=await fetch("/control",{method:"POST",headers:{...headers(),"Content-Type":"application/json"},body:JSON.stringify({command,source_channel:"cockpit",source_message_id:crypto.randomUUID(),idempotency_key:`cockpit:${crypto.randomUUID()}`})});if(res.status===401){showAuth();return}const out=await res.json();if(!res.ok||out.status!=="EXECUTED")throw new Error(out.failure_reason||out.error||out.message||"Command rejected");toast(out.message||"Command executed");setTimeout(load,350)}catch(err){toast(err.message,true)}}
window.review=(id,decision)=>sendCommand(`/${decision} ${id}`);window.goalCommand=(action,id)=>sendCommand(`/goal ${action} ${id}`);window.workCommand=(action,id)=>sendCommand(`/${action} ${id}`);
window.answerQuestion=id=>{const answer=prompt("この質問への回答を入力してください");if(answer?.trim())sendCommand(`/answer ${id} answer=${JSON.stringify(answer.trim())}`)};
window.changePriority=id=>{const value=prompt("Priority: LOW / NORMAL / HIGH / CRITICAL","HIGH");if(value)sendCommand(`/priority ${id} ${value.toUpperCase()}`)};
window.changeProvider=id=>{const provider=prompt("Provider name or id");if(provider)sendCommand(`/provider ${id} PREFER ${JSON.stringify(provider)}`)};
$("#new-goal").onclick=()=>{const objective=prompt("Goal objective");if(!objective?.trim())return;const title=prompt("Goal title",objective.trim().slice(0,60))||objective.trim();sendCommand(`/goal create title=${JSON.stringify(title)} objective=${JSON.stringify(objective.trim())} priority=NORMAL`)};
function toast(message,error=false){const t=$("#toast");t.textContent=message;t.className=error?"show error":"show";setTimeout(()=>t.className="",3200)}
load();
'''


__all__ = ["APP_JS", "INDEX_HTML", "STYLES_CSS"]
